"use strict";
import { useState } from "react";
import { Flex, Text, styled as uiStyled } from "ui/src";
const ToggleContainer = uiStyled(Flex, {
  flexDirection: "row",
  backgroundColor: "$surface3",
  borderRadius: "$roundedFull",
  padding: 2,
  gap: 2
});
const ToggleButton = uiStyled(Flex, {
  paddingHorizontal: "$spacing12",
  paddingVertical: "$spacing4",
  borderRadius: "$roundedFull",
  cursor: "pointer",
  justifyContent: "center",
  alignItems: "center",
  variants: {
    active: {
      true: {
        backgroundColor: "$surface1"
      }
    }
  }
});
export default function CurrencyToggle() {
  const [currency, setCurrency] = useState("USDC");
  return <ToggleContainer>
      <ToggleButton active={currency === "USDC"} onPress={() => setCurrency("USDC")}>
        <Text variant="buttonLabel4" color={currency === "USDC" ? "$neutral1" : "$neutral2"}>
          USDC
        </Text>
      </ToggleButton>
      <ToggleButton active={currency === "USD"} onPress={() => setCurrency("USD")}>
        <Text variant="buttonLabel4" color={currency === "USD" ? "$neutral1" : "$neutral2"}>
          USD
        </Text>
      </ToggleButton>
    </ToggleContainer>;
}
